// Don't block a dispatcher — a long sync call starves other coroutines.
// Never call Thread.sleep() on Default or Main; use delay().

// Cold flow — the builder runs once per collector
fun ticker(): Flow<Int> = flow {
  var i = 0
  while (true) {
    emit(i++)
    delay(1000)
  }
}

suspend fun observe() {
  ticker()
    .filter { it % 2 == 0 }
    .take(5)
    .collect { println(it) }
}

// Typeahead — flatMapLatest cancels the previous request
fun search(query: Flow<String>): Flow<List<Result>> =
  query
    .debounce(300)
    .distinctUntilChanged()
    .filter { it.length >= 2 }
    .flatMapLatest { q -> flow { emit(api.search(q)) } }
    .catch { emit(emptyList()) }          // upstream errors only

// Wrapping a callback API — channel + awaitClose
fun locations(client: LocationClient): Flow<Location> = callbackFlow {
  val listener = LocationListener { trySend(it) }
  client.register(listener)
  awaitClose { client.unregister(listener) }   // runs on cancellation
}

