// ✅ channelFlow when several coroutines must emit
val merged = channelFlow {
  launch { socket.messages().collect { send(it) } }
  launch { polling().collect { send(it) } }
  awaitClose { socket.close() }
}

suspend fun Call.await(): Response = suspendCancellableCoroutine { cont ->
  enqueue(object : Callback {
    override fun onResponse(call: Call, response: Response) {
      cont.resume(response)                       // resume exactly once
    }
    override fun onFailure(call: Call, e: IOException) {
      cont.resumeWithException(e)
    }
  })
  cont.invokeOnCancellation { cancel() }          // stop the HTTP call
}

// Many values instead of one — callbackFlow
fun LocationClient.updates(): Flow<Location> = callbackFlow {
  val listener = LocationListener { trySend(it) }
  requestUpdates(listener)
  awaitClose { removeUpdates(listener) }          // runs on cancellation
}

