class MainDispatcherRule(
  private val dispatcher: TestDispatcher = StandardTestDispatcher(),
) : TestWatcher() {
  override fun starting(d: Description) = Dispatchers.setMain(dispatcher)
  override fun finished(d: Description) = Dispatchers.resetMain()
}

class SearchViewModelTest {
  @get:Rule val mainRule = MainDispatcherRule()

  @Test
  fun `emits loading then results`() = runTest {
    val vm = SearchViewModel(FakeRepo(delayMs = 1_000))

    val states = mutableListOf<UiState>()
    backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) {
      vm.state.toList(states)              // cancelled when the test ends
    }

    vm.search("kotlin")
    runCurrent()
    assertEquals(UiState.Loading, states.last())

    advanceUntilIdle()                     // virtual time, no real waiting
    assertEquals(2, (states.last() as UiState.Results).items.size)
  }

  @Test
  fun `turbine reads the same stream`() = runTest {
    val vm = SearchViewModel(FakeRepo())
    vm.state.test {
      assertEquals(UiState.Empty, awaitItem())
      vm.search("kotlin")
      assertTrue(awaitItem() is UiState.Results)
      cancelAndIgnoreRemainingEvents()
    }
  }
}

