// ✅ Mutex when several fields must move together
class Cart {
  private val mutex = Mutex()
  private val items = mutableListOf<Item>()
  private var total = 0L

  suspend fun add(item: Item) = mutex.withLock {
    items += item
    total += item.price
  }
}

