// ❌ Accidentally sequential — awaited before the next one starts
suspend fun slow(): Dashboard {
  val user = coroutineScope { async { api.user() }.await() }
  val feed = coroutineScope { async { api.feed() }.await() }
  return Dashboard(user, feed, emptyList())
}

// Partial results: one failure must not sink the screen
suspend fun loadTolerant(): Dashboard = supervisorScope {
  val user = async { api.user() }
  val badges = async { api.badges() }
  Dashboard(
    user = user.await(),
    feed = emptyList(),
    badges = runCatching { badges.await() }.getOrDefault(emptyList()),
  )
}

